import { expect, test } from "vitest";
import { UserSchema } from "../src/models/user.schema";
import type { User } from "../src/models/user";

const user: User = { id: "1", email: "a@b.co", name: "A", createdAt: new Date(), updatedAt: new Date() };

test("accepts a valid user", () => {
  const parsed: User = UserSchema.parse(user);
  expect(parsed).toEqual(user);
});

test("rejects an invalid email", () => {
  expect(UserSchema.safeParse({ ...user, email: "nope" }).success).toBe(false);
});

